    const agendar = () => { if (!pedido) pedido = requestAnimationFrame(atualizar); };
    addEventListener('scroll', agendar, { passive: true });
    addEventListener('resize', agendar);
    new ResizeObserver(agendar).observe(document.body);
    atualizar();
